const $ = (selector, root = document) => root.querySelector(selector);
const esc = value => String(value ?? '').replace(/[&<>"']/g, char => ({ '&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;' })[char]);
const brl = value => new Intl.NumberFormat('pt-BR',{style:'currency',currency:'BRL'}).format(value);
const state = { gifts:[], memories:[], guests:[], venues:[], story:null, event:null, design:null, admin:null, payments:null, paymentsEnabled:false, webhookToken:'', category:'Todos', search:'', adminTab:'visao-geral', adminSearch:'' };
let weddingSlug=location.pathname.match(/^\/casamento\/([a-z0-9]+(?:-[a-z0-9]+)*)\/?$/)?.[1]||'suzy-e-junior';
let liveEvents;
let designCssVersion='0';
