let targetDate=new Date('2027-03-18T10:00:00-03:00');function updateCountdown(){let seconds=Math.max(0,Math.floor((targetDate-Date.now())/1000));const values={days:Math.floor(seconds/86400),hours:Math.floor(seconds%86400/3600),minutes:Math.floor(seconds%3600/60),seconds:seconds%60};for(const [id,value] of Object.entries(values))$('#'+id).textContent=String(value).padStart(2,'0')};updateCountdown();setInterval(updateCountdown,1000);
